<script setup lang="ts">
import {ref} from 'vue';import {register} from '../api/client';
const emit=defineEmits<{registered:[name:string];cancel:[]}>();
const form=ref({loginName:'',password:'',nickname:'',role:'STUDENT',grade:1}),busy=ref(false),error=ref('');
async function submit(){if(busy.value)return;busy.value=true;error.value='';try{await register(form.value);const name=form.value.loginName;form.value.password='';emit('registered',name);}catch(e){error.value=e instanceof Error?e.message:'注册失败，请重试';}finally{busy.value=false;}}
</script>
<template><section><button class="back" @click="emit('cancel')">‹ 返回登录</button><p class="eyebrow">建立自己的学习记录</p><h1>注册新账号</h1><p class="error" v-if="error" role="alert">{{error}}</p><form @submit.prevent="submit"><label for="registerRole">身份</label><select id="registerRole" v-model="form.role"><option value="STUDENT">学生</option><option value="PARENT">家长</option></select><label for="registerName">登录名</label><input id="registerName" v-model="form.loginName" minlength="3" maxlength="64" pattern="[A-Za-z0-9_-]+" autocomplete="username" required><p class="muted">3—64位字母、数字、下划线或短横线</p><label for="registerNickname">昵称</label><input id="registerNickname" v-model="form.nickname" maxlength="64" required><template v-if="form.role==='STUDENT'"><label for="registerGrade">年级</label><select id="registerGrade" v-model.number="form.grade"><option v-for="n in [1,2,3]" :key="n" :value="n">{{n}}年级</option></select></template><label for="registerPassword">密码</label><input id="registerPassword" v-model="form.password" type="password" minlength="8" maxlength="72" autocomplete="new-password" required><p class="muted">至少8位；不要与其他平台共用密码。</p><button class="primary" :disabled="busy">{{busy?'正在注册…':'确认注册'}}</button></form></section></template>
